const grid=document.querySelector('#projects');
function render(filter='all'){grid.innerHTML=projects.filter(p=>filter==='all'||p.category===filter).map(p=>`<article class="project-card"><div class="project-visual" style="background:${p.color}">${p.name==='GabbiDoc'?`<div class="chat-preview"><div class="chat-header"><span class="chat-avatar">G</span><div><strong>GabbiDoc</strong><small>Kiki · AI health assistant</small></div><span>•••</span></div><div class="chat-body"><div class="chat-bubble">Hi! I’m Kiki, your AI health assistant from GabbiDoc.<small>Illustrative welcome message</small></div><div class="chat-bubble sent">What can I do here?</div><div class="chat-bubble">Describe symptoms<br>Upload a lab result<br>View your health profile<br>Manage subscription plans</div></div></div>`:p.image?`<img src="assets/${p.image}" alt="${p.name}: ${p.evidence}" loading="lazy">`:`<div class="mock"><div class="mock-top"><strong>${p.name}</strong><span>Product overview ↗</span></div><h4>${p.name==='Gabbi Health'?'Care, connected.':p.name==='BuildKids'?'Small builders. Big ideas.':p.name==='Qoray'?'Mobility, managed.':p.name==='VEER'?'Better journeys start here.':p.name==='Intervia'?'Interviews meet AI.':'Learn. Challenge. Grow.'}</h4><p>${p.summary}</p><div class="mock-row">${p.mock.map(x=>`<span>${x}</span>`).join('')}</div></div>`}<span class="mock-label">${p.imageLabel||(p.image?'LOCAL APP SCREENSHOT':p.name==='GabbiDoc'?'ILLUSTRATIVE CONVERSATION · NO PATIENT DATA':'ILLUSTRATIVE PRODUCT PREVIEW')}</span></div><div class="project-meta"><div><h3>${p.name}</h3><p>${p.type} / ${p.stack}</p></div><button data-project="${p.name}" aria-label="Read ${p.name} case study">↗</button></div></article>`).join('');}
render();
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false')});button.classList.add('active');button.setAttribute('aria-pressed','true');render(button.dataset.filter)}));
const dialog=document.querySelector('dialog');grid.addEventListener('click',event=>{const button=event.target.closest('[data-project]');if(!button)return;const p=projects.find(p=>p.name===button.dataset.project);document.querySelector('#project-detail').innerHTML=`<div class="eyebrow">PROJECT NOTES / ${p.type.toUpperCase()}</div><h2>${p.name}</h2><p>${p.summary}</p><div class="detail-tags">${p.stack}</div>${p.gallery?`<div class="project-gallery">${p.gallery.map(item=>`<figure><a href="assets/${item.src}" target="_blank" rel="noopener noreferrer" aria-label="Open full screenshot: ${item.caption}"><img src="assets/${item.src}" alt="${item.caption}"></a><figcaption>${item.caption} · Open full size ↗</figcaption></figure>`).join('')}</div>`:''}<h3>The problem</h3><p>${p.problem}</p><h3>The build</h3><p>${p.build}</p><h3>The engineering lesson</h3><p>${p.lesson}</p><div class="project-destinations">${p.links.map(([label,url])=>`<a class="text-link" href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`).join('')}</div><small>${p.evidence}</small>`;dialog.showModal()});document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}});
document.querySelector('#brief-form').addEventListener('submit',event=>{event.preventDefault();const text=document.querySelector('#brief').value.trim();if(!text)return;const brief=`PROJECT BRIEF\n\nThe idea\n${text}\n\nWho is it for?\n\nWhat problem should it solve?\n\nMust-have features\n\nTimeline\n\nBudget range\n\nYour contact details\n`;const url=URL.createObjectURL(new Blob([brief],{type:'text/plain'}));const link=document.createElement('a');link.href=url;link.download='project-brief.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#brief-status').textContent='Your brief has been downloaded. Fill in the remaining details to prepare for our conversation. Send it to daotechnology18@gmail.com or share it on WhatsApp. This form does not send a message.'});
